/* ─────────────────────────────────────────────────────────
   COMPONENT
───────────────────────────────────────────────────────── */

interface UttarakhandMapProps {
  onOpenBookingModal?: (name: string) => void;
}

export const UttarakhandMap: React.FC<UttarakhandMapProps> = ({ onOpenBookingModal }) => {
  const [activeId, setActiveId] = useState<string | null>(null);
  const [hoverId, setHoverId] = useState<string | null>(null);

  const active = DISTRICTS.find((d) => d.id === activeId) ?? null;

  const handleClick = (id: string) => {
    setActiveId((prev) => (prev === id ? null : id));
  };

  return (
    <section className="py-16 sm:py-20 px-4 sm:px-6 lg:px-8 max-w-7xl mx-auto w-full">
      {/* Header */}
      <div className="text-center mb-10">
        <div className="inline-flex items-center gap-2 px-3.5 py-1.5 rounded-full bg-brand-orange/10 border border-brand-orange/20 text-brand-orange text-xs font-bold uppercase tracking-wider mb-3">
          <MapPin className="w-3.5 h-3.5" />
          <span>Explore by District</span>
        </div>
        <h2 className="text-3xl sm:text-4xl font-extrabold text-nav-text tracking-tight">
          Uttarakhand <span className="text-brand-orange">Interactive Map</span>
        </h2>
        <p className="mt-2 text-sm text-body-text max-w-xl mx-auto">
          Click any district to see its top destinations.
        </p>
      </div>

      {/* Map + Panel */}
      <div className="grid grid-cols-1 lg:grid-cols-5 gap-6 items-start">

        {/* SVG Map */}
        <div className="lg:col-span-3 bg-white rounded-2xl border border-gray-200 shadow-sm p-4 sm:p-6 overflow-hidden">
          <svg
            viewBox="50 30 1150 1050"
            className="w-full h-auto"
            xmlns="http://www.w3.org/2000/svg"
          >
            {DISTRICTS.map((d) => {
              const isActive = activeId === d.id;
              const isHover = hoverId === d.id;
              return (
                <g key={d.id}>
                  <path
                    d={d.path}
                    fill={
                      isActive
                        ? '#E8671A'
                        : isHover
                        ? '#c2905e'
                        : d.division === 'Garhwal'
                        ? '#b5d5b8'
                        : '#a8ccd4'
                    }
                    stroke="#fff"
                    strokeWidth={isActive ? 2.5 : 1.5}
                    className="cursor-pointer transition-colors duration-150"
                    onClick={() => handleClick(d.id)}
                    onMouseEnter={() => setHoverId(d.id)}
                    onMouseLeave={() => setHoverId(null)}
                  />
                  {/* District name label */}
                  <text
                    x={d.center.x}
                    y={d.center.y}
                    textAnchor="middle"
                    fontSize="28"
                    fontWeight="700"
                    fill={isActive ? '#fff' : '#1a2e1d'}
                    className="pointer-events-none select-none"
                    style={{ textShadow: '0 1px 3px rgba(0,0,0,0.3)', fontFamily: 'inherit' }}
                  >
                    {d.name}
                  </text>
                </g>
              );
            })}
          </svg>
          {/* Legend */}
          <div className="flex items-center gap-5 mt-3 pt-3 border-t border-gray-100 text-xs text-body-text justify-center">
            <span className="flex items-center gap-1.5">
              <span className="w-3 h-3 rounded-sm inline-block" style={{ background: '#b5d5b8' }} />
              Garhwal Division
            </span>
            <span className="flex items-center gap-1.5">
              <span className="w-3 h-3 rounded-sm inline-block" style={{ background: '#a8ccd4' }} />
              Kumaon Division
            </span>
            <span className="flex items-center gap-1.5">
              <span className="w-3 h-3 rounded-sm inline-block bg-brand-orange" />
              Selected
            </span>
          </div>
        </div>

        {/* Destination Panel */}
        <div className="lg:col-span-2">
          {!active ? (
            /* Placeholder when nothing selected */
            <div className="flex flex-col items-center justify-center h-64 rounded-2xl border-2 border-dashed border-gray-200 bg-gray-50 text-center px-6">
              <MapPin className="w-8 h-8 text-gray-300 mb-3" />
              <p className="text-sm font-semibold text-gray-400">Select a district on the map</p>
              <p className="text-xs text-gray-400 mt-1">to see its destinations</p>
            </div>
          ) : (
            <div className="bg-white rounded-2xl border border-gray-200 shadow-sm p-5 sm:p-6">
              {/* Panel header */}
              <div className="flex items-start justify-between mb-4">
                <div>
                  <span className={`inline-block text-[10px] font-bold uppercase tracking-widest px-2.5 py-1 rounded-full mb-1.5 ${
                    active.division === 'Garhwal'
                      ? 'bg-green-50 text-green-700'
                      : 'bg-blue-50 text-blue-700'
                  }`}>
                    {active.division} Division
                  </span>
                  <h3 className="text-xl font-extrabold text-nav-text leading-tight">
                    {active.name}
                  </h3>
                </div>
                <button
                  onClick={() => setActiveId(null)}
                  className="p-1.5 rounded-lg hover:bg-gray-100 text-gray-400 hover:text-gray-600 transition-colors"
                  aria-label="Close"
                >
                  <X className="w-4 h-4" />
                </button>
              </div>

              {/* Destination list */}
              <p className="text-[11px] uppercase font-bold tracking-wider text-gray-400 mb-3">
                Top Destinations — {active.destinations.length}
              </p>
              <ul className="space-y-2">
                {active.destinations.map((dest) => (
                  <li key={dest.id}>
                    <Link
                      to={`/destinations/${dest.id}`}
                      className="flex items-center gap-3 p-3 rounded-xl border border-gray-100 hover:border-brand-orange/40 hover:bg-brand-orange/5 transition-all group"
                    >
                      <span className="w-2 h-2 rounded-full bg-brand-orange shrink-0 group-hover:scale-110 transition-transform" />
                      <span className="text-sm font-semibold text-nav-text group-hover:text-brand-orange transition-colors">
                        {dest.name}
                      </span>
                    </Link>
                  </li>
                ))}
              </ul>

              {/* CTA */}
              {onOpenBookingModal && (
                <button
                  type="button"
                  onClick={() => onOpenBookingModal(`${active.name} Tour`)}
                  className="mt-5 w-full py-2.5 rounded-xl bg-brand-orange text-white text-sm font-bold hover:bg-brand-orange/90 transition-colors"
                >
                  Plan a Trip to {active.name} →
                </button>
              )}
            </div>
          )}
        </div>

      </div>
    </section>
  );
};
